import{_ as o,o as t,c as a,a1 as s}from"./chunks/framework.DceXOx8u.js";const g=JSON.parse('{"title":"Upgrade notes: channels and plugins","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/guide/upgrade-channels-plugins"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/guide/upgrade-channels-plugins"}]]},"headers":[],"relativePath":"guide/upgrade-channels-plugins.md","filePath":"guide/upgrade-channels-plugins.md"}'),d={name:"guide/upgrade-channels-plugins.md"};function n(i,e,r,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="upgrade-notes-channels-and-plugins" tabindex="-1">Upgrade notes: channels and plugins <a class="header-anchor" href="#upgrade-notes-channels-and-plugins" aria-label="Permalink to &quot;Upgrade notes: channels and plugins&quot;">​</a></h1><p>These are the changes since the first alpha (<code>@botmesh/core@2.0.0-alpha.2</code>, the rest at <code>0.2.0-alpha.0</code>) that can change how an existing bot behaves, for the channel, store and plugin packages. Each one says what changed and what to do. Most bots need no change.</p><h2 id="public-packages" tabindex="-1">Public packages <a class="header-anchor" href="#public-packages" aria-label="Permalink to &quot;Public packages&quot;">​</a></h2><h3 id="botmesh-baileys" tabindex="-1"><code>@botmesh/baileys</code> <a class="header-anchor" href="#botmesh-baileys" aria-label="Permalink to &quot;`@botmesh/baileys`&quot;">​</a></h3><p><strong><code>toJid()</code> throws on input it cannot turn into a JID.</strong> It returned <code>&#39;@s.whatsapp.net&#39;</code> for an input without digits, and an invalid <code>…@g.us:&lt;user&gt;</code> string for <code>{ groupId, userId }</code>. Both now throw a <code>TypeError</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toJid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ groupId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;120363000000000000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, userId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;573001112233&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// before: invalid string; now: TypeError</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toJid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ groupId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;120363000000000000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })                         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;120363000000000000@g.us&#39;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toJid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;573001112233&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;573001112233@s.whatsapp.net&#39;</span></span></code></pre></div><p>A group participant has no JID of its own: use the group JID for the chat and <code>toJid(userId)</code> for the person.</p><p><strong>Text edits reach the bot.</strong> An edited message used to be dropped. It now arrives as a message with the new text and the <strong>original</strong> <code>ref.id</code>, like on Telegram. <code>isEditedMessage(ctx)</code> tells it apart. The core dedupe lets an edit through and still drops an identical retry. Only an edit of a message this process has seen, sent in the same chat by the user who sends the edit, is delivered: an edit naming someone else&#39;s message, one of the bot&#39;s own or one from another chat is dropped, and so is an edit whose original is no longer in the provider&#39;s message cache (for example after a restart). To keep the old behaviour:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaileysProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ session: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-bot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, editedMessages: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ignore&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><h3 id="botmesh-ai" tabindex="-1"><code>@botmesh/ai</code> <a class="header-anchor" href="#botmesh-ai" aria-label="Permalink to &quot;`@botmesh/ai`&quot;">​</a></h3><p><strong><code>provider: &#39;openai&#39;</code> with a <code>baseUrl</code> sends <code>max_tokens</code>.</strong> For any <code>baseUrl</code> other than <code>api.openai.com</code> or Azure OpenAI (<code>*.openai.azure.com</code>, <code>*.cognitiveservices.azure.com</code>, or an Azure AI Foundry <code>*.services.ai.azure.com</code> endpoint under <code>/openai</code>), the output-token cap now goes in <code>max_tokens</code>, which OpenAI-compatible servers (vLLM, LM Studio, gateways) expect. If your <code>baseUrl</code> is a proxy in front of OpenAI and you use an o-series or gpt-5 model, set the field back:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aiPlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;openai&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, baseUrl: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://my-proxy.example/v1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, maxTokensField: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;max_completion_tokens&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p><strong>Memory options fail fast.</strong> An invalid <code>memory.maxFactLength</code>, <code>memory.maxFacts</code> or <code>memory.ttl</code> now throws a <code>RangeError</code> from <code>aiPlugin()</code> instead of failing at <code>plug()</code> (or, for <code>maxFactLength</code>, silently dropping every fact).</p><p><strong><code>onStreamEnd</code> has a fixed contract.</strong> <code>GenerateInput.onStreamEnd(info)</code> (an <code>AIStreamEndInfo</code>: <code>stopReason</code>, plus <code>usage</code> on Anthropic and Gemini) is called exactly once per <code>stream()</code> call, after the last chunk and before the iteration completes, and only when the stream ends normally: never when it fails, is aborted or the consumer breaks out early. An exception thrown by the callback fails the consumer&#39;s iteration. Every built-in provider and <code>MockAIProvider</code> follow it, including the abort rule when the client ignores <code>signal</code> (an aborted stream skips the callback and rejects with the abort reason); a custom <code>AIProvider</code> that calls <code>onStreamEnd</code> should too (check <code>signal.aborted</code> before calling it).</p><p><strong>Entries and frozen data.</strong> <code>MockAIProvider</code> moved to <code>@botmesh/ai/testing</code>, the plugin&#39;s helpers and the SDK wire type names to <code>@botmesh/ai/internal</code>, and the exported vocabularies, presets and texts are frozen. See <a href="./stable-migration#botmesh-ai-entries">Migrating to the stable API</a>.</p><h3 id="botmesh-meta" tabindex="-1"><code>@botmesh/meta</code> <a class="header-anchor" href="#botmesh-meta" aria-label="Permalink to &quot;`@botmesh/meta`&quot;">​</a></h3><ul><li><strong>Interactive limits are checked before sending.</strong> A <code>buttons</code> or <code>card</code> with no button, repeated button ids or titles (compared after the 20-character cut), a list with no rows, more than 10 rows, or repeated row ids now reject with <code>UnsupportedContentError</code>. Graph rejected them before too, but with an opaque error after the request.</li><li><strong>An interactive reply that is not a press</strong> (for example <code>call_permission_reply</code>) arrives as an <code>unknown</code> message with the payload in <code>ctx.ref.native</code>, not as a <code>button</code> interaction with empty data. A handler that matched those interactions must read the message instead.</li><li>Media uploads have their own timeout, <code>uploadTimeoutMs</code> (5 minutes by default).</li><li><strong>New <code>lang</code> option</strong> for the labels <code>publishForm()</code> bakes into a Flow (default <code>&#39;en&#39;</code>): set it to your bot&#39;s <code>BotConfig.lang</code>. <code>publishForm(def, { lang })</code> overrides it.</li><li><strong>Deprecated (removal in v3):</strong> <code>toProviderError</code> (use <code>toGraphError</code> from <code>@botmesh/graph-core</code>), <code>GraphClient</code> (transport internals), the re-exported <code>verifyChallenge</code>/<code>verifySignature</code> (use <code>provider.verifyChallenge(query)</code> and <code>provider.ingest()</code>, or import them from <code>@botmesh/graph-core</code>) and <code>debug</code> (pass a <code>logger</code>). <code>phoneNumberId</code> is typed <code>string | number</code>.</li></ul><h3 id="botmesh-telegram" tabindex="-1"><code>@botmesh/telegram</code> <a class="header-anchor" href="#botmesh-telegram" aria-label="Permalink to &quot;`@botmesh/telegram`&quot;">​</a></h3><ul><li>In webhook mode, <code>ingest()</code> after <code>stop()</code> answers <code>503</code> and emits nothing (Telegram redelivers the Update after the restart). Hosts that started the provider again do not need to change anything.</li><li>File uploads have their own timeout, <code>uploadTimeoutMs</code> (5 minutes by default).</li><li><strong>Polls are sent non-anonymous and their votes reach the bot.</strong> Each <code>poll_answer</code> becomes a <code>&#39;poll&#39;</code> event with the same shape as on WhatsApp (<code>vote.ref</code>, <code>vote.senderId</code>, <code>vote.options</code> with <code>voters</code>). Members of the chat can see who voted. Channels refuse public-voter polls, so a poll to a channel is retried once as anonymous (no votes) and the channel is remembered. To keep anonymous polls (and receive no votes):</li></ul><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TelegramProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ token, anonymousPolls: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><ul><li><strong><code>pollTimeoutMs</code></strong> replaces <code>pollTimeout</code> (seconds, deprecated): <code>pollTimeout: 30</code> is <code>pollTimeoutMs: 30_000</code>. <code>toProviderError</code> is now <code>toTelegramError</code> (the old name is a deprecated alias), <code>debug</code> is deprecated (pass a <code>logger</code>), and the wire helpers <code>parseUpdate</code>, <code>parsePollAnswer</code>, <code>toOutbound</code> and <code>MEDIA_UPLOAD</code> are <code>@experimental</code>.</li></ul><h3 id="botmesh-sqlite-store" tabindex="-1"><code>@botmesh/sqlite-store</code> <a class="header-anchor" href="#botmesh-sqlite-store" aria-label="Permalink to &quot;`@botmesh/sqlite-store`&quot;">​</a></h3><p><code>saveMessage</code> and <code>setCursor</code> throw a <code>TypeError</code> for a message id, chat id, cursor key or cursor value with a lone UTF-16 surrogate (before, SQLite stored it as U+FFFD and two ids could share a row). Escape or drop such characters before storing them.</p><p><strong>Schema versioning.</strong> The database records its layout in <code>PRAGMA user_version</code> (<code>SQLITE_SCHEMA_VERSION</code>, now <code>2</code>). Opening a file written by an earlier release (version <code>0</code> or <code>1</code>) migrates it in place, keeping every row; nothing to do. Version <code>2</code> folds the durable scheduler&#39;s tables (<code>schedules</code>, <code>schedule_fences</code>) and the durability table (<code>durable</code>) into the versioned migrations: they used to be created ad hoc the first time <code>schedules()</code> or <code>durability()</code> was called, and are now created when the file is opened. A file written by a <strong>newer</strong> release is refused with <code>SQLiteSchemaVersionError</code> (<code>code: &#39;SQLITE_SCHEMA_TOO_NEW&#39;</code>) and left untouched: downgrades are not supported, so back up the file before upgrading if you may need to roll back.</p><p><strong>Rolling back to the previous alpha.</strong> The previous alpha writes and reads schema version <code>1</code>. Once this release opens a file, the file is at version <code>2</code> and the previous alpha refuses it with <code>SQLITE_SCHEMA_TOO_NEW</code> on its next start, even if the app never calls <code>schedules()</code> or <code>durability()</code>. This also applies during a rolling deploy: a process still on the previous alpha that shares the file fails when it restarts, so stop every process on the old version before the first one on the new version opens the file. To roll back, restore the copy taken before the upgrade. No rows were changed by the migration (it only adds tables with <code>CREATE TABLE IF NOT EXISTS</code>), so if you have no copy you can set <code>PRAGMA user_version = 1</code> by hand with the <code>sqlite3</code> CLI while no process has the file open, and the previous alpha opens it again. The version bump exists so that later migrations can assume these tables exist; without it they would stay outside the version.</p><p>New options: <code>busyTimeoutMs</code> (default 5000, <code>PRAGMA busy_timeout</code>) and a <code>logger</code> that takes any <code>LoggerLike</code>. The exported <code>SCHEDULES_SCHEMA</code> and <code>DURABLE_SCHEMA</code> DDL strings are deprecated.</p><h3 id="botmesh-messenger-and-botmesh-instagram" tabindex="-1"><code>@botmesh/messenger</code> and <code>@botmesh/instagram</code> <a class="header-anchor" href="#botmesh-messenger-and-botmesh-instagram" aria-label="Permalink to &quot;`@botmesh/messenger` and `@botmesh/instagram`&quot;">​</a></h3><p>Both channels are public from the beta (<code>1.0.0-beta</code>), so their first npm release already has the frozen entry. Inside the monorepo or a fork, an import of a removed name fails to compile:</p><table tabindex="0"><thead><tr><th>Removed from the main entry</th><th>Use instead</th></tr></thead><tbody><tr><td><code>toProviderError</code></td><td><code>toMessengerError</code> / <code>toInstagramError</code></td></tr><tr><td><code>verifyChallenge</code>, <code>verifySignature</code> re-exports</td><td><code>provider.verifyChallenge(query)</code> / <code>provider.ingest()</code>, or <code>@botmesh/graph-core</code></td></tr><tr><td><code>parseInbound</code>, <code>toOutbound</code>, <code>toOutboundMessages</code> (Messenger)</td><td><code>@botmesh/messenger/internal</code> (no semver)</td></tr><tr><td><code>GraphClient</code>, <code>parseInbound</code>, <code>toOutbound</code> (Instagram)</td><td><code>@botmesh/instagram/internal</code> (no semver)</td></tr><tr><td><code>GraphSendResponse</code> (Instagram)</td><td><code>InstagramSendResponse</code> (same shape)</td></tr></tbody></table><p>The <code>debug</code> option is deprecated in both: pass a <code>logger</code> instead. More than 3 buttons (or 10 list rows) on Messenger, or more than 13 quick replies on Instagram, reject with <code>UnsupportedContentError</code> instead of being cut.</p><h3 id="botmesh-evolution-botmesh-wppconnect-and-botmesh-wa-gateway-kit" tabindex="-1"><code>@botmesh/evolution</code>, <code>@botmesh/wppconnect</code> and <code>@botmesh/wa-gateway-kit</code> <a class="header-anchor" href="#botmesh-evolution-botmesh-wppconnect-and-botmesh-wa-gateway-kit" aria-label="Permalink to &quot;`@botmesh/evolution`, `@botmesh/wppconnect` and `@botmesh/wa-gateway-kit`&quot;">​</a></h3><p>New on npm in the beta (they were private before). If you used them from the monorepo:</p><ul><li>The webhook parsers, outbound mappers and media tokens (<code>parseWebhook</code>, <code>parseMessage</code>, <code>toOutbound</code>, <code>numberedMenu</code>, <code>keyFromRef</code>, <code>target</code>, <code>jidOf</code>…) and Evolution&#39;s JWT helpers (<code>verifyHs256Jwt</code>, <code>signHs256Jwt</code>) moved to <code>@botmesh/evolution/internal</code> and <code>@botmesh/wppconnect/internal</code>, which have no semver guarantee.</li><li><code>WaIdentityStore</code> and <code>normalizeJid</code> are no longer re-exported by the providers: import them from <code>@botmesh/wa-gateway-kit</code>. <code>IdentityPersistence</code> and <code>RestHttpOptions</code> stay on the providers&#39; main entry.</li><li>The <code>debug</code> option was removed: pass a <code>logger</code> (<code>pino({ level: &#39;debug&#39; })</code>).</li><li>Invalid options throw a <code>TypeError</code> (it was a plain <code>Error</code>; the messages are the same). Also, <code>baseUrl</code> no longer accepts credentials (<code>user:pass@</code>), a query string or a fragment, <code>identityCacheSize</code> must be a positive integer (or <code>Infinity</code>), and <code>http.timeoutMs</code> / <code>http.maxBytes</code> are checked when the provider is built, not on the first request.</li><li>Only an <code>http(s)</code> URL is handed to the gateway to download. <code>{ url }</code> is always a link, as on Meta and Telegram: it accepts <code>http(s)</code> or a base64 <code>data:</code> URI (sent inline), and a local path or <code>file:</code> URL there rejects with <code>UnsupportedContentError</code> instead of being read (it used to be passed as is, and the gateway tried to open that path on its own host). Send a local file as <code>{ path }</code> or a plain path string; the bot reads it and sends it as base64.</li></ul><h2 id="plugins-promoted-to-npm" tabindex="-1">Plugins promoted to npm <a class="header-anchor" href="#plugins-promoted-to-npm" aria-label="Permalink to &quot;Plugins promoted to npm&quot;">​</a></h2><p><code>@botmesh/rag</code>, <code>@botmesh/voice</code>, <code>@botmesh/nlu</code>, <code>@botmesh/dialogflow</code>, <code>@botmesh/chatwoot</code>, <code>@botmesh/tickets</code> and <code>@botmesh/moderation</code> are published on npm from the beta (<code>1.0.0-beta</code>). Code that used them from the monorepo (<code>workspace:*</code>) needs these changes:</p><ul><li><strong>Helpers moved to a <code>/internal</code> entry</strong> (no semver; applications rarely need them): <code>@botmesh/rag/internal</code> (<code>splitMarkdownSections</code>, <code>resolveChunkOptions</code>, <code>cosine</code>, <code>hashText</code>, <code>tokenize</code>, <code>resolveEmbedder</code>, <code>createPdfParser</code>), <code>@botmesh/voice/internal</code> (<code>trimPunctuation</code>, <code>resolveStt</code>, <code>resolveTts</code>, <code>OPENAI_TTS_MIMETYPES</code>, <code>elevenLabsMimetype</code>, <code>estimateOggDurationSec</code>, <code>estimateDurationSec</code>, <code>sniffMimetype</code>), <code>@botmesh/dialogflow/internal</code> (<code>normalizeEsResult</code>, <code>normalizeCxResult</code>, <code>toSessionId</code>, <code>parseCredentials</code>, <code>createServiceAccountJwt</code>, <code>DIALOGFLOW_SCOPE</code>, <code>DEFAULT_TOKEN_URI</code>), <code>@botmesh/chatwoot/internal</code> (<code>ChatwootMapping</code>, <code>verifyWebhook</code>, <code>inboundText</code>, <code>outboundText</code>), <code>@botmesh/tickets/internal</code> (<code>renderTemplate</code>, <code>localClock</code>) and <code>@botmesh/moderation/internal</code> (<code>findLinks</code>, <code>findInviteLinks</code>, <code>compileTerms</code>, <code>foldText</code>).</li><li><strong><code>@botmesh/dialogflow</code>:</strong> <code>dialogflowPlugin</code> is the canonical name and <code>dialogflowContext</code> a deprecated alias. <code>languageCode</code> defaults to <code>&#39;en&#39;</code> (it was <code>&#39;es&#39;</code>): set it to your agent&#39;s language. In groups, <code>sessionScope</code> defaults to <code>&#39;participant&#39;</code> (one Dialogflow session per member, like conversations); set <code>sessionScope: &#39;chat&#39;</code> to keep one session per group. Mistyped options (<code>minConfidence: 80</code>, an unknown <code>fulfillment</code>…) now throw <code>DialogflowError</code> (<code>INVALID_CONFIG</code>) at <code>bot.plug()</code>, and texts over 256 characters are no longer sent (<code>maxTextLength</code>).</li><li><strong>Frozen data:</strong> <code>DEFAULT_VOICE_LIMITS</code>, <code>SUPPORTED_EXTENSIONS</code> (rag), <code>TICKET_PRIORITIES</code> and <code>TICKET_STATUSES</code> can no longer be mutated; copy them first.</li><li><strong><code>@botmesh/chatwoot</code>:</strong> a webhook signature without <code>x-chatwoot-timestamp</code> is rejected (it never expired, so a captured request could be replayed). Set <code>webhookAllowUntimedSignature: true</code> only for a sender that cannot add the timestamp.</li><li><strong><code>@botmesh/tickets</code>:</strong> <code>TicketKeyValue</code> has an optional <code>setIf</code>. A custom storage that implements it switches the desk to shared mode (safe for replicas).</li></ul><h2 id="packages-that-were-private" tabindex="-1">Packages that were private <a class="header-anchor" href="#packages-that-were-private" aria-label="Permalink to &quot;Packages that were private&quot;">​</a></h2><p>These notes matter for code that used the packages from the monorepo or a fork before the beta. <code>@botmesh/discord</code>, <code>@botmesh/email</code> and <code>@botmesh/flow-schema</code> are on npm from the beta; <code>@botmesh/tiktok</code> and the product packages are still private.</p><ul><li><strong><code>@botmesh/discord</code>:</strong> <code>ctx.interaction.id</code> (<code>interactionId</code>) is the bare interaction id; the token stays in the provider, and the alpha <code>&quot;&lt;id&gt;:&lt;token&gt;&quot;</code> form of <code>acknowledgeInteraction()</code> was removed before the first publish (only ids the provider received are known). Interactions the bot does not acknowledge within <code>autoAcknowledgeMs</code> (2 s; the alpha <code>autoAckMs</code> alias was removed) are deferred for it; set <code>autoAcknowledgeMs: false</code> to keep doing it yourself. Sent messages carry <code>allowed_mentions: { parse: [&#39;users&#39;] }</code> unless set (<code>allowedMentions</code> changes it), so <code>@everyone</code>, <code>@here</code> and role mentions no longer ping by default. Message edits (<code>MESSAGE_UPDATE</code>) now arrive as messages with the original <code>ref.id</code> (<code>isEditedMessage(ctx)</code>; <code>editedMessages: &#39;ignore&#39;</code> drops them).</li><li><strong>Error mappers renamed</strong> (old names are deprecated aliases): <code>toTikTokError</code>, <code>toEmailError</code>. <code>toDiscordError</code> has no alias: <code>toProviderError</code> was removed from <code>@botmesh/discord</code> before its first publish.</li><li><strong>Product stores:</strong> <code>InboxStore.erase</code>, <code>ContactStore.erase</code> and <code>DeploymentStore.prune</code> are new required methods, and <code>DeploymentStore.list</code> / <code>InboxStore.listNotes</code> accept an <code>after</code> cursor. A custom store must add them (the shared conformance suites in <code>test-utils/</code> check them). <code>attachInbox()</code> without <code>tenantId</code> now files conversations under the bot&#39;s own tenant instead of <code>&#39;local&#39;</code>.</li><li><strong><code>@botmesh/flow-schema</code>:</strong> <code>publishFlow()</code> takes any registry with a compatible <code>publish()</code> (a <code>DeploymentRegistry</code> fits) and no longer depends on <code>@botmesh/deployments</code> at run time.</li></ul>',39)])])}const m=o(d,[["render",n]]);export{g as __pageData,m as default};
